// Spring Boot - Add Permissions-Policy via Security Configuration
// SecurityConfig.java

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.web.SecurityFilterChain;

@Configuration
@EnableWebSecurity
public class SecurityConfig {

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        http
            .headers(headers -> headers
                // Note: Spring Security doesn't have built-in Permissions-Policy support yet
                // Use custom filter below
            )
            .authorizeHttpRequests(auth -> auth
                .anyRequest().permitAll()
            );

        return http.build();
    }
}

// Custom Filter for Permissions-Policy
import javax.servlet.*;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import org.springframework.stereotype.Component;

@Component
public class PermissionsPolicyFilter implements Filter {

    @Override
    public void doFilter(ServletRequest request, ServletResponse response, 
                        FilterChain chain) throws IOException, ServletException {
        HttpServletResponse httpResponse = (HttpServletResponse) response;

        // Restrictive policy - deny most features
        String policy = String.join(", ", 
            "geolocation=()",
            "camera=()",
            "microphone=()",
            "payment=()",
            "usb=()",
            "interest-cohort=()",  // Disable FLoC
            "accelerometer=()",
            "gyroscope=()",
            "magnetometer=()"
        );

        httpResponse.setHeader("Permissions-Policy", policy);

        // Alternative: Allow specific features for same-origin
        // String policy = "geolocation=(self), camera=(self), microphone=(self)";

        chain.doFilter(request, response);
    }
}

// Example: Allow specific features
@Component
public class CustomPermissionsPolicyFilter implements Filter {

    @Override
    public void doFilter(ServletRequest request, ServletResponse response,
                        FilterChain chain) throws IOException, ServletException {
        HttpServletResponse httpResponse = (HttpServletResponse) response;

        // Policy for video conferencing app
        String policy = String.join(", ",
            "geolocation=(self)",
            "camera=(self)",
            "microphone=(self)",
            "payment=()",
            "usb=()",
            "fullscreen=(self)",
            "picture-in-picture=(self)"
        );

        httpResponse.setHeader("Permissions-Policy", policy);

        chain.doFilter(request, response);
    }
}

