import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.web.servlet.MockMvc;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringBootTest
@AutoConfigureMockMvc
public class PermissionsPolicyTest {

    @Autowired
    private MockMvc mockMvc;

    @Test
    public void shouldHavePermissionsPolicyHeader() throws Exception {
        mockMvc.perform(get("/"))
            .andExpect(status().isOk())
            .andExpect(header().exists("Permissions-Policy"));
    }

    @Test
    public void shouldRestrictSensitiveFeatures() throws Exception {
        String policy = mockMvc.perform(get("/"))
            .andReturn()
            .getResponse()
            .getHeader("Permissions-Policy");

        assertNotNull(policy);
        // Verify geolocation is restricted
        assertTrue(policy.contains("geolocation=()") || 
                   policy.contains("geolocation=(self)"));
    }

    @Test
    public void allEndpointsShouldHaveHeader() throws Exception {
        String[] endpoints = {"/", "/api/data", "/video-call"};

        for (String endpoint : endpoints) {
            mockMvc.perform(get(endpoint))
                .andExpect(header().exists("Permissions-Policy"));
        }
    }
}

