    {
        "geolocation=()",
        "camera=()",
        "microphone=()",
        "payment=()",
        "usb=()",
        "interest-cohort=()",
        "accelerometer=()",
        "gyroscope=()"
    });

    context.Response.Headers.Add("Permissions-Policy", policy);

    await next();
});

app.UseRouting();
app.UseAuthorization();

app.MapControllerRoute(
    name: "default",
    pattern: "{controller=Home}/{action=Index}/{id?}");

app.Run();

// Alternative: Reusable middleware class
public class PermissionsPolicyMiddleware
{
    private readonly RequestDelegate _next;
    private readonly string _policy;

    public PermissionsPolicyMiddleware(RequestDelegate next, string policy = null)
    {
        _next = next;
        _policy = policy ?? BuildDefaultPolicy();
    }

    public async Task InvokeAsync(HttpContext context)
    {
        context.Response.Headers.Add("Permissions-Policy", _policy);
        await _next(context);
    }

    private static string BuildDefaultPolicy()
    {
        return string.Join(", ", new[]
        {
            "geolocation=()",
            "camera=()",
            "microphone=()",
            "payment=()",
            "usb=()",
            "interest-cohort=()"
        });
    }
}

// Extension method
public static class PermissionsPolicyExtensions
{
    public static IApplicationBuilder UsePermissionsPolicy(
        this IApplicationBuilder builder, 
        string customPolicy = null)
    {
        return builder.UseMiddleware<PermissionsPolicyMiddleware>(customPolicy);
    }
}

