// Method 2: Feature-specific policies
public class FeatureBasedPermissionsPolicyMiddleware
{
    private readonly RequestDelegate _next;

    public FeatureBasedPermissionsPolicyMiddleware(RequestDelegate next)
    {
        _next = next;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        var path = context.Request.Path.Value?.ToLower() ?? "";

        string policy;

        if (path.Contains("/video-call"))
        {
            // Allow camera/microphone for video calls
            policy = "geolocation=(self), camera=(self), microphone=(self), payment=()";
        }
        else if (path.Contains("/checkout"))
        {
            // Allow payment API for checkout
            policy = "geolocation=(self), camera=(), microphone=(), payment=(self)";
        }
        else
        {
            // Restrictive default
            policy = "geolocation=(), camera=(), microphone=(), payment=(), usb=()";
        }

        context.Response.Headers.Add("Permissions-Policy", policy);

        await _next(context);
    }
}

