# Method 1: Custom middleware
# middleware.py
class PermissionsPolicyMiddleware:
    def __init__(self, get_response):
        self.get_response = get_response

    def __call__(self, request):
        response = self.get_response(request)

        # Restrictive policy
        policy = ', '.join([
            'geolocation=()',
            'camera=()',
            'microphone=()',
            'payment=()',
            'usb=()',
            'interest-cohort=()',  # Disable FLoC
        ])

        response['Permissions-Policy'] = policy

        return response

# Add to settings.py:
# MIDDLEWARE = [
#     'your_app.middleware.PermissionsPolicyMiddleware',
#     # ... other middleware
# ]

# Method 2: Feature-specific policies
class DynamicPermissionsPolicyMiddleware:
    def __init__(self, get_response):
        self.get_response = get_response

    def __call__(self, request):
        response = self.get_response(request)

        path = request.path.lower()

        if '/video-call' in path:
            # Allow camera/microphone for video calls
            policy = 'geolocation=(self), camera=(self), microphone=(self), payment=()'
        elif '/checkout' in path:
            # Allow payment API for checkout
            policy = 'geolocation=(self), camera=(), microphone=(), payment=(self)'
        else:
            # Restrictive default
            policy = ', '.join([
                'geolocation=()',
                'camera=()',
                'microphone=()',
                'payment=()',
                'usb=()',
            ])

        response['Permissions-Policy'] = policy

        return response

# Method 3: View-specific decorator
def permissions_policy(policy_dict):
    """Decorator to set custom Permissions-Policy for specific views"""
    def decorator(view_func):
        def wrapper(request, *args, **kwargs):
            response = view_func(request, *args, **kwargs)

            # Build policy from dictionary
            policy_parts = []
            for feature, allowlist in policy_dict.items():
                if allowlist == 'none':
                    policy_parts.append(f'{feature}=()')
                elif allowlist == 'self':
                    policy_parts.append(f'{feature}=(self)')
                else:
                    policy_parts.append(f'{feature}=({allowlist})')

            response['Permissions-Policy'] = ', '.join(policy_parts)
            return response
        return wrapper
    return decorator

# Usage:
@permissions_policy({
    'geolocation': 'self',
    'camera': 'self',
    'microphone': 'self',
    'payment': 'none'
})
def video_call_view(request):
    return render(request, 'video_call.html')

@permissions_policy({
    'geolocation': 'none',
    'camera': 'none',
    'microphone': 'none',
    'payment': 'none'
})
def public_view(request):
    return render(request, 'public.html')

